-- =====================================================================
-- QLDT - Dữ liệu khởi tạo (seed data)
-- Sinh theo: Tài liệu thiết kế phần mềm v1.0 - mục 3.1 (8 bảng, quan hệ)
--           Quy ước API và JSON (FE-BE) v1.0 - mục 3.2 (đối chiếu tên cột)
--
-- Số lượng:
--   ADMIN      : 2 tài khoản
--   LECTURERS  : 10 giảng viên
--   STUDENTS   : 1000 sinh viên
--   SUBJECTS   : 100 môn học
--   SEMESTERS  : 3 học kỳ (2025.1, 2025.2, 2026.1)
--   ROOMS      : 30 phòng học
--   SECTIONS   : 400 lớp học phần
--   REGISTRATIONS: 11983 bản ghi đăng ký
--
-- Tài khoản dùng chung, mật khẩu: 123456  (đã băm Bcrypt)
--   admin / admin02                       - Ban quản lý
--   gv001 .. gv010               - Giảng viên (mã GV001 .. GV010)
--   sv20210001 .. sv20211000   - Sinh viên (mã số SV = hậu tố tên đăng nhập)
--
-- Dữ liệu đã bảo đảm: không trùng mã, không xung đột phòng / giảng viên,
-- không trùng môn và không trùng lịch cho sinh viên, current_enrollment
-- khớp đúng số bản ghi REGISTRATIONS của lớp.
--
-- Cách nạp:  mysql -u root -p < schema.sql   rồi   mysql -u root -p < seed.sql
-- =====================================================================

USE qldt;
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

TRUNCATE TABLE REGISTRATIONS;
TRUNCATE TABLE COURSE_SECTIONS;
TRUNCATE TABLE LECTURERS;
TRUNCATE TABLE STUDENTS;
TRUNCATE TABLE SUBJECTS;
TRUNCATE TABLE SEMESTERS;
TRUNCATE TABLE ROOMS;
TRUNCATE TABLE USERS;

SET FOREIGN_KEY_CHECKS = 1;

-- USERS (tài khoản của mọi vai trò)






-- STUDENTS (hồ sơ chuyên biệt, liên kết 1-1 với USERS)





-- LECTURERS (hồ sơ chuyên biệt, liên kết 1-1 với USERS)

-- SUBJECTS (danh mục môn học)

-- SEMESTERS (học kỳ)

-- ROOMS (phòng học)

-- COURSE_SECTIONS (bảng trung tâm: SUBJECTS + SEMESTERS + ROOMS + LECTURERS)


-- REGISTRATIONS (liên kết nhiều-nhiều giữa STUDENTS và COURSE_SECTIONS)



























































